# Auto-generated embedded templates
import os
import gzip
import base64

_DATA = {'scandinavian_oak.jpg': '', 'milano_modern.jpg': '', 'soho_loft.jpg': ''}

def ensure_templates():
    templates_dir = os.path.join(os.path.dirname(__file__), 'templates')
    os.makedirs(templates_dir, exist_ok=True)
    for filename, b64_data in _DATA.items():
        target = os.path.join(templates_dir, filename)
        if not os.path.exists(target) or os.path.getsize(target) < 1000:
            raw = gzip.decompress(base64.b64decode(b64_data.encode('ascii')))
            with open(target, 'wb') as f:
                f.write(raw)
    return templates_dir

if __name__ == '__main__':
    ensure_templates()
    print('Templates unpacked successfully.')
